SET NOCOUNT ON;SET XACT_ABORT ON;SELECT * FROM lab.Evidence ORDER BY Stage;SELECT SUM(user_object_reserved_page_count) UserObjectPages,SUM(internal_object_reserved_page_count) InternalObjectPages,SUM(version_store_reserved_page_count) VersionStorePages,SUM(unallocated_extent_page_count) FreePages FROM tempdb.sys.dm_db_file_space_usage;IF NOT EXISTS(SELECT 1 FROM lab.Evidence w JOIN lab.Evidence b ON b.Stage='BASELINE' WHERE w.Stage='WORKLOAD' AND w.UserPages>b.UserPages) THROW 51006,'FAIL_RESULT_CONTRACT: User-Object-Delta fehlt.',1;PRINT 'SQLPERF_SUMMARY|PASS|OK';
